list_payment_gateways.code:
final response = await client.paymentGateways.listPaymentGateways(
    queryParams: {'limit': 20, 'offset': 0, 'promotional': 'false'});
final gateways = (response.map as Map)['payment_gateways'] as List;
for (final gateway in gateways) {
  print('${(gateway as Map)['id']} ${gateway['code']} ${gateway['enabled']}');
}

count_payment_gateways.code:
final response = await client.paymentGateways
    .countPaymentGateways(queryParams: {'exclude': 'PIS,CHQ'});
print((response.map as Map)['total']);

get_payment_gateway.code:
final response = await client.paymentGateways.getPaymentGateway(2);
final gateway = (response.map as Map)['payment_gateway'] as Map;
print('${gateway['code']} ${gateway['name']} ${gateway['enabled']}');
print(gateway['allowed_for']);

update_payment_gateway.code:
final response = await client.paymentGateways.updatePaymentGateway(2, {
  'information': 'Make cheques payable to Example Store.',
});
final gateway = (response.map as Map)['payment_gateway'] as Map;
print('${gateway['code']} ${gateway['information']}');

patch_payment_gateway.code:
final response = await client.paymentGateways.patchPaymentGateway(2, {
  'allowed_for': {'store_pickup': false},
});
final gateway = (response.map as Map)['payment_gateway'] as Map;
print('${gateway['code']} ${gateway['allowed_for']}');
